package edu.smartstudy.parent;
import edu.smartstudy.user.*;import edu.smartstudy.planning.*;import edu.smartstudy.focus.*;import edu.smartstudy.quiz.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/parents")public class ParentController{private final ParentStudentLinkRepository links;private final UserRepository users;private final StudyTaskRepository tasks;private final FocusSessionRepository focus;private final QuizAttemptRepository attempts;public ParentController(ParentStudentLinkRepository links,UserRepository users,StudyTaskRepository tasks,FocusSessionRepository focus,QuizAttemptRepository attempts){this.links=links;this.users=users;this.tasks=tasks;this.focus=focus;this.attempts=attempts;}private Long id(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}private Map<String,Object> user(User u){return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail());}public record LinkRequest(@Email @NotBlank String studentEmail){}@PostMapping("/links")@PreAuthorize("hasRole('PARENT')")public ResponseEntity<?> requestLink(@RequestBody @Valid LinkRequest input,Authentication auth){Long parent=id(auth);User child=users.findByEmailIgnoreCase(input.studentEmail().trim()).filter(u->u.getRole().equals("STUDENT")).orElse(null);if(child==null)return ResponseEntity.notFound().build();if(links.existsByParentIdAndStudentId(parent,child.getId()))return ResponseEntity.status(409).body(Map.of("error","A link request already exists."));return ResponseEntity.status(201).body(Map.of("id",links.save(new ParentStudentLink(parent,child.getId())).getId(),"student",user(child),"status","PENDING"));}@GetMapping("/children")@PreAuthorize("hasRole('PARENT')")public List<Map<String,Object>> children(Authentication auth){return links.findByParentIdAndStatusOrderByCreatedAtDesc(id(auth),"APPROVED").stream().map(l->users.findById(l.getStudentId()).map(this::user).orElse(null)).filter(Objects::nonNull).toList();}@GetMapping("/children/{studentId}/progress")@PreAuthorize("hasRole('PARENT')")public ResponseEntity<?> progress(@PathVariable Long studentId,Authentication auth){Long parent=id(auth);if(links.findByParentIdAndStatusOrderByCreatedAtDesc(parent,"APPROVED").stream().noneMatch(l->l.getStudentId().equals(studentId)))return ResponseEntity.notFound().build();User child=users.findById(studentId).orElseThrow();long total=tasks.countByStudentId(studentId),done=tasks.countByStudentIdAndStatus(studentId,"COMPLETED");List<QuizAttempt> results=attempts.findTop100ByStudentIdOrderBySubmittedAtDesc(studentId);int scored=results.stream().mapToInt(QuizAttempt::getScore).sum(),possible=results.stream().mapToInt(QuizAttempt::getTotalQuestions).sum();return ResponseEntity.ok(Map.of("student",user(child),"studyMinutes",focus.totalSeconds(studentId)/60,"tasksCompleted",done,"tasksTotal",total,"taskCompletionPercent",total==0?0:Math.round(100.0*done/total),"quizAttempts",results.size(),"quizAccuracyPercent",possible==0?0:Math.round(100.0*scored/possible)));}@GetMapping("/requests")@PreAuthorize("hasRole('STUDENT')")public List<Map<String,Object>> requests(Authentication auth){return links.findByStudentIdAndStatusOrderByCreatedAtDesc(id(auth),"PENDING").stream().map(l->Map.<String,Object>of("id",l.getId(),"parent",users.findById(l.getParentId()).map(this::user).orElse(Map.of()),"createdAt",l.getCreatedAt())).toList();}@PostMapping("/links/{linkId}/accept")@PreAuthorize("hasRole('STUDENT')")public ResponseEntity<?> accept(@PathVariable Long linkId,Authentication auth){return links.findByIdAndStudentId(linkId,id(auth)).<ResponseEntity<?>>map(link->{link.accept();return ResponseEntity.ok(links.save(link));}).orElseGet(()->ResponseEntity.notFound().build());}}
